// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/config", wrapper.RunConfig)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/runs", wrapper.ListRuns)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/runs", wrapper.CreateRun)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/runs/{id}", wrapper.DeleteRun)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/runs/{id}", wrapper.RunByID)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/runs/{id}/export.csv", wrapper.ExportRunCSV)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/runs/{id}/reenable", wrapper.ReenableRun)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/runs/{id}/report", wrapper.RunReport)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/runs/{id}/stop", wrapper.StopRun)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions", wrapper.ListSessions)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/sessions", wrapper.CreateSession)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/sessions/{id}", wrapper.DeleteSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions/{id}", wrapper.SessionByID)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions/{id}/export.csv", wrapper.ExportSessionCSV)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/sessions/{id}/reenable", wrapper.ReenableSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions/{id}/report", wrapper.SessionReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/sessions/{id}/samples", wrapper.SessionSamples)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/sessions/{id}/stop", wrapper.StopSession)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/healthz", wrapper.Healthz)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/readyz", wrapper.Readyz)
	})

	return r
}

